// Mirrors: https://git.hubteam.com/HubSpot/hubspot-cli-private/blob/master/lib/projects/localDev/helpers/devSessionsApi.ts
const DEV_SESSIONS_API_PATH = 'projects-localdev/2025-09/dev-sessions';
// Mirrors: https://git.hubteam.com/HubSpot/hubspot-cli-private/blob/master/lib/projects/localDev/DevSessionManager.ts#L115
const HEARTBEAT_INTERVAL_MS = 30_000;
export class DevSessionManager {
    accountId;
    logger;
    sessionId;
    heartbeatTimer;
    constructor(accountId, logger) {
        this.accountId = accountId;
        this.logger = logger;
    }
    // Mirrors: https://git.hubteam.com/HubSpot/hubspot-cli-private/blob/master/lib/projects/localDev/DevSessionManager.ts#L51
    // Mirrors: https://git.hubteam.com/HubSpot/hubspot-cli-private/blob/master/lib/projects/localDev/helpers/devSessionsApi.ts#L6
    async register(ports) {
        const { http } = await import('@hubspot/local-dev-lib/http');
        const response = await http.post(this.accountId, {
            url: `${DEV_SESSIONS_API_PATH}/register`,
            params: { force: true },
            data: { ports },
        });
        this.sessionId = response.data.sessionId;
        this.startHeartbeat();
        this.logger.info(`Local dev session registered (ID: ${this.sessionId}). Extension is now in local dev mode.`);
    }
    // Mirrors: https://git.hubteam.com/HubSpot/hubspot-cli-private/blob/master/lib/projects/localDev/DevSessionManager.ts#L86
    // Mirrors: https://git.hubteam.com/HubSpot/hubspot-cli-private/blob/master/lib/projects/localDev/helpers/devSessionsApi.ts#L19
    startHeartbeat() {
        this.heartbeatTimer = setInterval(async () => {
            if (!this.sessionId)
                return;
            try {
                const { http } = await import('@hubspot/local-dev-lib/http');
                await http.post(this.accountId, {
                    url: `${DEV_SESSIONS_API_PATH}/${this.sessionId}/heartbeat`,
                    data: {},
                });
            }
            catch {
                // heartbeat failures are non-fatal
            }
        }, HEARTBEAT_INTERVAL_MS);
        // don't keep the process alive just for heartbeats
        this.heartbeatTimer.unref();
    }
    // Mirrors: https://git.hubteam.com/HubSpot/hubspot-cli-private/blob/master/lib/projects/localDev/DevSessionManager.ts#L118
    // Mirrors: https://git.hubteam.com/HubSpot/hubspot-cli-private/blob/master/lib/projects/localDev/helpers/devSessionsApi.ts#L32
    async cleanup() {
        if (this.heartbeatTimer) {
            clearInterval(this.heartbeatTimer);
            this.heartbeatTimer = undefined;
        }
        if (!this.sessionId)
            return;
        try {
            const { http } = await import('@hubspot/local-dev-lib/http');
            await http.delete(this.accountId, {
                url: `${DEV_SESSIONS_API_PATH}/${this.sessionId}`,
            });
            this.logger.info('Local dev session ended.');
        }
        catch {
            // cleanup failures are non-fatal
        }
    }
}
export async function createDevSessionManager(accountId, logger) {
    const { getConfigAccountIfExists } = await import('@hubspot/local-dev-lib/config');
    const account = getConfigAccountIfExists(accountId);
    if (!account) {
        logger.warn(`No HubSpot account with ID ${accountId} found in ~/.hscli/config.yml. ` +
            `Pass a real account ID via --account-id to enable in-app local dev mode.`);
        return null;
    }
    return new DevSessionManager(accountId, logger);
}
